// Full Metro lowering followed by the real Native pattern sources. The host
// is a stand-in, not device or AT evidence. Candidate data is generated by
// the project scanner, not hand-authored styles or a second variant evaluator.
import assert from 'node:assert/strict'
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { createRequire, registerHooks } from 'node:module'
import path from 'node:path'
import { after, mock, test } from 'node:test'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { createCompiler, openCandidateCache } from '@hozo/compiler'
import { loadTheme } from '@hozo/tailwind'
import { loadNativeModule, type Tree } from './native-render.ts'

const require = createRequire(import.meta.url)
const react = require('react')
const renderer = require('react-test-renderer')
const stub = require('react-native')
const root = fileURLToPath(new URL('../../../', import.meta.url))
const theme = await loadTheme('@import "tailwindcss"; @theme { --color-brand: #123456; }', root)
const source = `import { Chip, ColorPicker, Pagination, Stepper, CommandPalette, OtpInput, cx } from '@hozo/core'
export const classes = {
  chip: 'p-2 hover:bg-brand focus-visible:outline-2 disabled:opacity-25 aria-pressed:rounded-lg',
  swatch: 'p-2 aria-checked:rounded-lg disabled:opacity-25 hover:opacity-50 focus-visible:outline-2 active:border-2 hover:bg-brand',
  selectedSwatch: 'aria-checked:outline-offset-4',
  page: 'p-2 disabled:opacity-25 aria-disabled:mt-2 aria-selected:rounded-lg hover:border-2 focus-visible:outline-2',
  currentPage: 'hover:opacity-75',
  disabledPage: 'disabled:outline-offset-4 aria-disabled:outline-offset-8',
  step: 'p-2 disabled:opacity-25 hover:opacity-50 focus-visible:outline-2',
  completed: 'hover:rounded-lg', current: 'focus:outline-offset-4', error: 'active:border-4',
  item: 'p-2 hover:bg-brand aria-selected:text-brand aria-disabled:opacity-25 disabled:rounded-lg focus:outline-4 focus-visible:font-bold',
  activeItem: 'hover:outline-offset-4 focus-visible:outline-8',
  input: 'rounded-lg focus:outline-2 focus-visible:outline-offset-4 disabled:opacity-25 read-only:rounded-none aria-disabled:mt-2',
  changed: 'hover:opacity-75',
  unsupported: 'md:hover:opacity-25 not-focus:mt-1 aria-expanded:border-4',
  pointerInput: 'hover:opacity-25 active:opacity-50',
  mixed: 'p-4 opacity-75 rounded-none hover:bg-brand focus-visible:outline-2',
}
export function ChipProbe({ getClasses, extra, disabled }) {
  return <Chip defaultSelected onRemove={() => {}} disabled={disabled}
    removeClassName={getClasses()} removeStyle={extra}>Token</Chip>
}
export function RootChipProbe({ getClasses, extra, disabled, remove, selectable = true }) {
  return <Chip defaultSelected={selectable ? true : undefined} onRemove={remove} disabled={disabled}
    className={getClasses()} style={extra}>Token</Chip>
}
export function MixedChipProbe({ getClasses, getOtherClasses, extra, disabled }) {
  return <Chip defaultSelected disabled={disabled}
    className={cx('p-2 opacity-100 hover:opacity-50 not-focus:rounded-lg disabled:outline-offset-4', getClasses(), getOtherClasses())}
    style={extra}>Token</Chip>
}
export function MixedRemoveProbe({ getClasses, getOtherClasses, extra, disabled }) {
  return <Chip defaultSelected onRemove={() => {}} disabled={disabled}
    removeClassName={cx('p-2 opacity-100 hover:opacity-50 not-focus:rounded-lg disabled:outline-offset-4', getClasses(), getOtherClasses())}
    removeStyle={extra}>Token</Chip>
}
export function GuardedRemoveProbe({ getClasses, getGuard, getOtherClasses }) {
  return <Chip onRemove={() => {}}
    removeClassName={cx(getClasses(), getGuard() && 'p-2', getOtherClasses())}>Token</Chip>
}
export function OrderedRemoveProbe({ first, outer, inner, off, last, extra, remove = () => {} }) {
  return <Chip onRemove={remove}
    removeClassName={cx('not-focus:rounded-lg hover:opacity-50', first(), outer() ? inner() ? 'p-2' : 'p-4' : off() && 'p-6', last())}
    removeStyle={extra}>Token</Chip>
}
export function GuardedDecorationProbe({ cell, filled }) {
  return <OtpInput length={3} value="1" onChange={() => {}}
    cellClassName={cell() ? 'p-2' : 'p-4'} filledCellClassName={filled() && 'opacity-50'} />
}
export async function AwaitGuardProbe(wait) {
  return <Chip onRemove={() => {}} removeClassName={(await wait()) ? 'p-2' : 'p-4'} />
}
export function* YieldGuardProbe() {
  return <Chip onRemove={() => {}} removeClassName={(yield 'guard') ? 'p-2' : 'p-4'} />
}
export function ReceiverGuardProbe() {
  return <Chip onRemove={() => {}} removeClassName={this.read(arguments[0]) ? 'p-2' : 'p-4'} />
}
export function ColorProbe({ disabled, value, onChange, extra }) {
  return <ColorPicker accessibilityLabel="Colour" presets={['#ef4444', '#3b82f6']}
    defaultValue="#3b82f6" value={value} onChange={onChange} disabled={disabled}
    swatchClassName={classes.swatch} selectedSwatchClassName={classes.selectedSwatch}
    swatchStyle={extra} />
}
export function PageProbe({ page, getPageHref, onPageChange, extra }) {
  return <Pagination pageCount={3} page={page} getPageHref={getPageHref} onPageChange={onPageChange}
    itemClassName={classes.page} currentItemClassName={classes.currentPage}
    disabledItemClassName={classes.disabledPage} currentItemStyle={extra} />
}
export function MixedPageProbe({ getPageHref, getClasses, extra }) {
  return <Pagination pageCount={3} getPageHref={getPageHref}
    itemClassName={cx('outline-0 rounded-none enabled:outline-2 disabled:outline-offset-4 not-disabled:rounded-lg aria-disabled:mt-2', getClasses())}
    itemStyle={extra} />
}
export function StepProbe({ steps, onStepPress, activeStep = 1, extra }) {
  return <Stepper steps={steps} onStepPress={onStepPress} activeStep={activeStep}
    stepClassName={classes.step} completedStepClassName={classes.completed}
    currentStepClassName={classes.current} errorStepClassName={classes.error}
    currentStepStyle={extra} />
}
export function CommandProbe({ commands, extra }) {
  return <CommandPalette open commands={commands} accessibilityLabel="Commands"
    itemClassName={classes.item} activeItemClassName={classes.activeItem} activeItemStyle={extra} />
}
export function OtpProbe({ disabled, readOnly, inputClasses = classes.input, extra }) {
  return <OtpInput accessibilityLabel="Code" value="12" length={4} disabled={disabled} readOnly={readOnly}
    cellClassName="size-8" inputClassName={inputClasses} inputStyle={extra} />
}`

const project = mkdtempSync(path.join(root, 'packages/tailwind-conformance/.pattern-project-'))
const cache = openCandidateCache()
cache.scanFile('Component.tsx', source, 1)
const sheet = path.join(project, 'node_modules/.hozo/candidates.native.js')
mkdirSync(path.dirname(sheet), { recursive: true })
writeFileSync(sheet, cache.renderNativeModule(theme))
// Metro redirects this import inside the source-distributed patterns too,
// not just the transformed author file. Keep the same project-wide sheet.
const hook = registerHooks({
  resolve(specifier, context, next) {
    return specifier === '@hozo/engine/project'
      ? { url: pathToFileURL(sheet).href, shortCircuit: true }
      : next(specifier, context)
  },
})
after(() => {
  hook.deregister()
  rmSync(project, { recursive: true, force: true })
})
const diagnostics = mock.method(console, 'warn', () => {})
const components = loadNativeModule(source, project, {
  root: project,
  compiler: createCompiler(theme),
})
diagnostics.mock.restore()
const classes = components.classes as Record<string, string>
const flat = (node: Tree) => stub.StyleSheet.flatten(node.props.style)
const hosts = (tree, role?: string) =>
  tree.root.findAll(
    (node: Tree) => node.type === 'Pressable' && (!role || node.props.accessibilityRole === role),
  )
function event(node: Tree, name: string) {
  assert.equal(typeof node.props[name], 'function', `${name} is not wired`)
  renderer.act(() => node.props[name]({ nativeEvent: {} }))
}
function mount(name: string, props = {}) {
  let tree: ReturnType<typeof renderer.create>
  renderer.act(() => {
    tree = renderer.create(react.createElement(components[name], props))
  })
  return {
    tree,
    update: (next) => renderer.act(() => tree.update(react.createElement(components[name], next))),
    unmount: () => renderer.act(() => tree.unmount()),
  }
}

test('compiled dynamic Chip root follows toggle versus composite ownership without rerunning the author', () => {
  let calls = 0
  let value: unknown = classes.chip
  const props = {
    getClasses: () => {
      calls++
      return value
    },
  }
  const view = mount('RootChipProbe', props)
  const toggle = () => hosts(view.tree, 'togglebutton')[0]
  try {
    assert.equal(calls, 1)
    assert.equal(flat(toggle()).borderRadius, 8, 'root sees its selected toggle')
    event(toggle(), 'onHoverIn')
    assert.equal(flat(toggle()).backgroundColor, '#123456')
    event(toggle(), 'onFocus')
    assert.equal(flat(toggle()).outlineWidth, 2)
    assert.equal(calls, 1)
    view.update({ ...props, disabled: true })
    assert.equal(flat(toggle()).opacity, 0.25)
    view.update({ ...props, disabled: true, extra: { opacity: 0.9 } })
    assert.equal(flat(toggle()).opacity, 0.9)

    view.update({ ...props, disabled: true, remove: () => {} })
    const row = () => view.tree.root.findAll((node: Tree) => node.type === 'View')[0]
    assert.equal(flat(row()).borderRadius, undefined, 'composite span is not aria-pressed')
    assert.equal(flat(row()).opacity, undefined, 'composite span is not :disabled')
    assert.equal(flat(row()).outlineWidth, undefined, 'a focused child never focuses the row')
    event(row(), 'onPointerEnter')
    assert.equal(flat(row()).backgroundColor, '#123456')
    value = classes.changed
    view.update({ ...props, remove: () => {} })
    assert.equal(flat(row()).opacity, 0.75)
    assert.equal(flat(row()).backgroundColor, undefined)
    for (value of [undefined, false, '']) {
      view.update({ ...props, remove: () => {} })
      assert.equal(flat(row()).opacity, undefined)
    }
    view.update({ ...props, selectable: false })
    assert.equal(hosts(view.tree).length, 0, 'plain chip does not gain an interactive wrapper')
  } finally {
    view.unmount()
  }
})

test('mixed Chip root retains AOT negation and resting/residual/state/explicit precedence', () => {
  const calls: string[] = []
  let value: unknown = classes.mixed
  const props = {
    getClasses: () => {
      calls.push('first')
      return value
    },
    getOtherClasses: () => {
      calls.push('second')
      return classes.changed
    },
  }
  const view = mount('MixedChipProbe', props)
  const toggle = () => hosts(view.tree, 'togglebutton')[0]
  try {
    assert.deepEqual(calls, ['first', 'second'])
    assert.equal(flat(toggle()).paddingTop, 16, 'dynamic resting beats compiled resting')
    assert.equal(flat(toggle()).opacity, 0.75)
    assert.equal(flat(toggle()).borderRadius, 8, 'AOT not-focus remains outside runtime subset')
    event(toggle(), 'onHoverIn')
    assert.equal(flat(toggle()).opacity, 0.5, 'compiled state follows both dynamic residuals')
    assert.equal(flat(toggle()).backgroundColor, '#123456')
    event(toggle(), 'onFocus')
    assert.equal(flat(toggle()).borderRadius, 0, 'negation switches off; dynamic resting remains')
    assert.equal(flat(toggle()).outlineWidth, 2, 'runtime still receives real focus facts')
    assert.deepEqual(calls, ['first', 'second'], 'events do not evaluate captured author calls')
    view.update({ ...props, disabled: true, extra: { opacity: 0.9 } })
    assert.equal(flat(toggle()).opacity, 0.9)
    assert.equal(flat(toggle()).outlineOffset, 4, 'static semantic alias sees actual owner facts')
    value = undefined
    view.update(props)
    assert.equal(flat(toggle()).backgroundColor, undefined, 'rerender discards old captures')
    assert.equal(flat(toggle()).paddingTop, 8)
  } finally {
    view.unmount()
  }
})

test('dynamic removal classes follow only removal state and evaluate the author expression once per render', () => {
  let calls = 0
  let value: unknown = classes.chip
  const props = {
    getClasses: () => {
      calls++
      return value
    },
  }
  const view = mount('ChipProbe', props)
  const remove = () => hosts(view.tree, 'button')[0]
  try {
    assert.equal(calls, 1)
    assert.equal(flat(remove()).backgroundColor, undefined)
    assert.equal(
      flat(remove()).borderRadius,
      undefined,
      'removal does not borrow the selected toggle',
    )
    event(remove(), 'onHoverIn')
    assert.equal(flat(remove()).backgroundColor, '#123456')
    assert.equal(calls, 1, 'owner state does not rerun the author expression')
    event(remove(), 'onFocus')
    assert.equal(flat(remove()).outlineWidth, 2)
    const row = view.tree.root.findAll((node: Tree) => node.type === 'View')[0]
    assert.equal(flat(row).outlineWidth, undefined, 'child focus does not focus the row')
    value = classes.changed
    view.update(props)
    assert.equal(flat(remove()).backgroundColor, undefined)
    assert.equal(flat(remove()).opacity, 0.75, 'new string sees the still-hovered owner')
    for (value of [undefined, false, '']) {
      view.update(props)
      assert.equal(flat(remove()).opacity, undefined, 'absent classes clear old styles')
    }
    value = classes.chip
    view.update({ ...props, disabled: true, extra: { opacity: 0.9 } })
    assert.equal(flat(remove()).opacity, 0.9)
    assert.equal(remove().props.disabled, true)
  } finally {
    view.unmount()
  }
})

