test('guarded secondary expressions preserve original short-circuit order and single author evaluation', () => {
  const calls: string[] = []
  const view = mount('GuardedRemoveProbe', {
    getClasses: () => {
      calls.push('first')
      return classes.mixed
    },
    getGuard: () => {
      calls.push('guard')
      return true
    },
    getOtherClasses: () => {
      calls.push('last')
      return classes.changed
    },
  })
  try {
    assert.deepEqual(calls, ['first', 'guard', 'last'])
    const remove = () => hosts(view.tree, 'button')[0]
    event(remove(), 'onHoverIn')
    event(remove(), 'onFocus')
    assert.deepEqual(calls, ['first', 'guard', 'last'])
    assert.equal(flat(remove()).backgroundColor, '#123456')
    assert.equal(flat(remove()).outlineWidth, 2)
  } finally {
    view.unmount()
  }
})

test('nested secondary guards skip inactive branches and retain captured values across owner events', () => {
  const calls: string[] = []
  let outer = true
  let inner = true
  let off = false
  const read = (name, value) => () => {
    calls.push(name)
    return value()
  }
  const props = {
    first: read('first', () => undefined),
    outer: read('outer', () => outer),
    inner: read('inner', () => inner),
    off: read('off', () => off),
    last: read('last', () => undefined),
  }
  const view = mount('OrderedRemoveProbe', props)
  const remove = () => hosts(view.tree, 'button')[0]
  try {
    assert.deepEqual(calls, ['first', 'outer', 'inner', 'last'])
    assert.equal(flat(remove()).paddingTop, 8)
    assert.equal(flat(remove()).borderRadius, 8)
    event(remove(), 'onHoverIn')
    event(remove(), 'onFocus')
    assert.equal(flat(remove()).opacity, 0.5)
    assert.equal(flat(remove()).borderRadius, undefined)
    assert.deepEqual(calls, ['first', 'outer', 'inner', 'last'])
    calls.length = 0
    inner = false
    view.update(props)
    assert.equal(flat(remove()).paddingTop, 16)
    assert.deepEqual(calls, ['first', 'outer', 'inner', 'last'])
    calls.length = 0
    outer = false
    view.update(props)
    assert.deepEqual(calls, ['first', 'outer', 'off', 'last'])
    assert.equal(flat(remove()).paddingTop, undefined, 'false AOT branches contribute no padding')
    calls.length = 0
    off = true
    view.update({ ...props, extra: { paddingTop: 31 } })
    assert.equal(flat(remove()).paddingTop, 31, 'explicit style remains last')
    assert.equal(flat(remove()).paddingBottom, 24)
    assert.deepEqual(calls, ['first', 'outer', 'off', 'last'])
    calls.length = 0
    view.update({ ...props, remove: null })
    assert.equal(hosts(view.tree, 'button').length, 0, 'no removal owner is invented')
    assert.deepEqual(
      calls,
      ['first', 'outer', 'off', 'last'],
      'author inputs still run when the slot is absent',
    )
  } finally {
    view.unmount()
  }
})

test('captured class inputs preserve await, yield, this and arguments in the authored scope', async () => {
  const style = (element) => stub.StyleSheet.flatten(element.props.hozoRemoveStyle({}))
  assert.equal(style(await components.AwaitGuardProbe(async () => true)).paddingTop, 8)
  const iterator = components.YieldGuardProbe()
  assert.deepEqual(iterator.next(), { value: 'guard', done: false })
  const result = iterator.next(false)
  assert.equal(result.done, true)
  assert.equal(style(result.value).paddingTop, 16)
  const receiver = {
    expected: {},
    read(value) {
      return value === this.expected
    },
  }
  assert.equal(style(components.ReceiverGuardProbe.call(receiver, receiver.expected)).paddingTop, 8)
  assert.equal(style(components.ReceiverGuardProbe.call(receiver, {})).paddingTop, 16)
  const calls = []
  assert.throws(
    () =>
      components.OrderedRemoveProbe({
        first() {
          calls.push('first')
        },
        outer() {
          calls.push('outer')
          throw new Error('guard failed')
        },
        last() {
          calls.push('last')
        },
      }),
    /guard failed/,
  )
  assert.deepEqual(calls, ['first', 'outer'], 'an abrupt guard skips every later input')
})

test('decorative slots capture independent predicates without borrowing interaction ownership', () => {
  const calls: string[] = []
  const props = {
    cell: () => {
      calls.push('cell')
      return true
    },
    filled: () => {
      calls.push('filled')
      return true
    },
  }
  const view = mount('GuardedDecorationProbe', props)
  try {
    assert.deepEqual(calls, ['cell', 'filled'])
    const cells = view.tree.root.findAll(
      (node: Tree) =>
        node.type === 'View' && stub.StyleSheet.flatten(node.props.style)?.paddingTop === 8,
    )
    assert.equal(cells.length, 3)
    assert.equal(flat(cells[0]).opacity, 0.5)
    assert.equal(flat(cells[1]).opacity, undefined, 'filled slot applies only to filled cells')
  } finally {
    view.unmount()
  }
})

test('dynamic swatches retain per-radio selection, pointer modality, explicit styles and preset colour', () => {
  const changes: string[] = []
  const props = { onChange: (value: string) => changes.push(value) }
  const view = mount('ColorProbe', props)
  const radios = () => hosts(view.tree, 'radio')
  try {
    const [red, blue] = radios()
    assert.equal(flat(red).borderRadius, undefined)
    assert.equal(flat(blue).borderRadius, 8)
    assert.equal(flat(blue).outlineOffset, 4)
    event(red, 'onHoverIn')
    assert.equal(flat(red).opacity, 0.5)
    assert.equal(flat(blue).opacity, undefined)
    assert.equal(flat(red).backgroundColor, '#ef4444', 'preset colour remains last')
    event(blue, 'onFocus')
    assert.equal(flat(blue).outlineWidth, 2)
    event(red, 'onPressIn')
    assert.equal(flat(red).borderWidth ?? flat(red).borderTopWidth, 2)
    event(red, 'onPressOut')
    event(red, 'onPress')
    assert.deepEqual(changes, ['#ef4444'])
    assert.equal(flat(radios()[0]).borderRadius, 8)
    assert.equal(flat(radios()[1]).borderRadius, undefined)
    assert.equal(flat(radios()[1]).outlineOffset, undefined)
    event(red, 'onHoverOut')
    view.update({ ...props, disabled: true })
    assert.equal(flat(radios()[0]).opacity, 0.25)
    assert.equal(radios()[0].props.disabled, true)
    view.update({ ...props, disabled: true, extra: { opacity: 0.8 } })
    assert.equal(flat(radios()[0]).opacity, 0.8)
  } finally {
    view.unmount()
  }
})

test('dynamic pagination slots keep current gates and button versus link boundary facts', () => {
  const view = mount('PageProbe')
  const buttons = () => hosts(view.tree)
  try {
    const [previous, one, two] = buttons()
    assert.equal(flat(previous).opacity, 0.25)
    assert.equal(flat(previous).outlineOffset, 4)
    assert.equal(flat(previous).marginTop, undefined)
    assert.equal(flat(one).borderRadius, undefined, 'selected announcement is not aria-selected')
    event(one, 'onHoverIn')
    event(two, 'onHoverIn')
    assert.equal(flat(one).opacity, 0.75)
    assert.equal(flat(two).opacity, undefined)
    event(two, 'onPress')
    assert.equal(flat(buttons()[2]).opacity, 0.75, 'current slot follows uncontrolled page')
    assert.equal(flat(buttons()[1]).opacity, undefined)
    view.update({
      page: 3,
      getPageHref: (page: number) => `/page/${page}`,
      extra: { opacity: 0.9 },
    })
    const next = buttons().at(-1)
    assert.equal(next.props.accessibilityRole, 'link')
    assert.equal(flat(next).opacity, undefined, 'a disabled link is not :disabled')
    assert.equal(flat(next).marginTop, 8)
    assert.equal(flat(next).outlineOffset, 8)
    assert.equal(flat(buttons()[3]).opacity, 0.9)
  } finally {
    view.unmount()
  }
})

test('mixed pagination classes keep enabled distinct from not-disabled when buttons become links', () => {
  let calls = 0
  const props = {
    getClasses: () => {
      calls++
      return 'opacity-75'
    },
  }
  const view = mount('MixedPageProbe', props)
  const controls = () => hosts(view.tree)
  try {
    assert.equal(calls, 1)
    assert.equal(flat(controls()[0]).outlineOffset, 4)
    assert.equal(flat(controls()[0]).outlineWidth, 0)
    assert.equal(flat(controls()[0]).borderRadius, 0)
    assert.equal(flat(controls()[1]).outlineWidth, 2)
    assert.equal(flat(controls()[1]).borderRadius, 8)
    view.update({ ...props, getPageHref: (page) => `/page/${page}` })
    assert.equal(calls, 2)
    assert.equal(flat(controls()[0]).outlineOffset, undefined, 'disabled link is not :disabled')
    assert.equal(flat(controls()[0]).outlineWidth, 0, 'link is not :enabled either')
    assert.equal(flat(controls()[0]).borderRadius, 8, 'but not-disabled does match it')
    assert.equal(flat(controls()[0]).marginTop, 8)
    assert.equal(flat(controls()[1]).outlineWidth, 0)
  } finally {
    view.unmount()
  }
})

test('dynamic step/status slots do not invent an interactive owner for descriptive steps', () => {
  const steps = [
    { label: 'Done' },
    { label: 'Now' },
    { label: 'Error', status: 'error' },
    { label: 'Later', disabled: true },
  ]
  const warn = mock.method(console, 'warn', () => {})
  const view = mount('StepProbe', { steps })
  try {
    assert.equal(hosts(view.tree).length, 0)
    const rows = () =>
      view.tree.root.findAll((node: Tree) => node.type === 'View' && node.props.accessible)
    for (const row of rows()) {
      for (const side of ['Top', 'Right', 'Bottom', 'Left']) {
        assert.equal(flat(row)[`padding${side}`], 8)
      }
      assert.equal(flat(row).opacity, undefined)
      assert.equal(flat(row).outlineWidth, undefined)
    }
    assert.ok(warn.mock.calls.some((call) => String(call.arguments[0]).includes('does not supply')))
    view.update({ steps, onStepPress: () => {} })
    const [done, current, error, later] = hosts(view.tree)
    event(done, 'onHoverIn')
    assert.equal(flat(done).borderRadius, 8)
    assert.equal(flat(current).borderRadius, undefined)
    event(current, 'onFocus')
    assert.equal(flat(current).outlineWidth, 2)
    assert.equal(flat(current).outlineOffset, 4)
    event(error, 'onPressIn')
    assert.equal(flat(error).borderWidth ?? flat(error).borderTopWidth, 4)
    assert.equal(flat(later).opacity, 0.25)
    view.update({ steps })
    assert.equal(hosts(view.tree).length, 0)
    assert.equal(flat(rows()[0]).opacity, undefined, 'removed button hover does not leak')
    assert.equal(flat(rows()[1]).outlineWidth, undefined)
  } finally {
    view.unmount()
    warn.mock.restore()
  }
})

test('dynamic command slots use option semantics and move their active gate with the query', () => {
  const calls: string[] = []
  const commands = [
    { id: 'a', label: 'Alpha', onSelect: () => calls.push('a') },
    { id: 'b', label: 'Beta', disabled: true, onSelect: () => calls.push('b') },
    { id: 'c', label: 'Gamma', onSelect: () => calls.push('c') },
  ]
  const view = mount('CommandProbe', { commands })
  const buttons = () => hosts(view.tree, 'button').filter((node) => node.props.accessibilityLabel)
  const text = (node) => node.findByType('Text')
  try {
    const [alpha, beta, gamma] = buttons()
    assert.equal(flat(text(alpha)).color, '#123456')
    assert.equal(flat(beta).opacity, 0.25)
    assert.equal(flat(beta).borderRadius, undefined, 'disabled option div is not :disabled')
    event(alpha, 'onFocus')
    event(alpha, 'onKeyDown')
    assert.equal(flat(alpha).outlineWidth, undefined, 'option does not borrow Native button focus')
    assert.equal(flat(text(alpha)).fontWeight, undefined)
    event(alpha, 'onHoverIn')
    assert.equal(flat(alpha).outlineOffset, 4)
    assert.equal(flat(gamma).outlineOffset, undefined)
    event(gamma, 'onHoverIn')
    assert.equal(flat(alpha).outlineOffset, undefined, 'hover changes the active command')
    assert.equal(flat(gamma).outlineOffset, 4)
    event(beta, 'onPress')
    assert.deepEqual(calls, [], 'disabled activation guard is retained')
    renderer.act(() => view.tree.root.findByType('TextInput').props.onChangeText('Gamma'))
    assert.equal(buttons().length, 1)
    assert.equal(flat(text(buttons()[0])).color, '#123456')
    assert.equal(flat(buttons()[0]).outlineOffset, 4)
    view.update({ commands, extra: { outlineOffset: 9 } })
    assert.equal(flat(buttons()[0]).outlineOffset, 9)
  } finally {
    view.unmount()
  }
})

test('dynamic OTP input classes retain mutability, focus and one transparent real field', () => {
  const view = mount('OtpProbe')
  const field = () => view.tree.root.findByType('TextInput')
  const frame = () =>
    view.tree.root.findAll(
      (node: Tree) => node.type === 'View' && node.props.pointerEvents === 'none',
    )[0]
  try {
    event(field(), 'onFocus')
    assert.equal(flat(frame()).outlineWidth, 2)
    assert.equal(flat(frame()).outlineOffset, 4)
    event(field(), 'onBlur')
    assert.equal(flat(frame()).outlineWidth, undefined)
    for (const disabled of [false, true])
      for (const readOnly of [false, true]) {
        view.update({ disabled, readOnly })
        assert.equal(view.tree.root.findAllByType('TextInput').length, 1)
        assert.equal(field().props.editable, !disabled && !readOnly)
        assert.equal(flat(frame()).borderRadius, disabled || readOnly ? 0 : 8)
        assert.equal(flat(frame()).marginTop, 0, 'fixed overlay geometry is retained')
        assert.equal(
          flat(frame()).opacity,
          disabled ? 0.25 : undefined,
          'mutability uses the field, not the decorative wrapper',
        )
        assert.equal(flat(field()).opacity, 0.011)
        assert.equal(flat(field()).color, 'transparent')
        assert.equal(flat(field()).width, '100%')
      }
    view.update({ extra: { outlineWidth: 7 } })
    event(field(), 'onFocus')
    assert.equal(flat(frame()).outlineWidth, 7)
    const warn = mock.method(console, 'warn', () => {})
    try {
      view.update({ inputClasses: `${classes.unsupported} ${classes.pointerInput}` })
      const warnings = warn.mock.calls.map((call) => String(call.arguments[0]))
      for (const name of [...classes.unsupported.split(' '), ...classes.pointerInput.split(' ')]) {
        assert.ok(
          warnings.some((message) => message.includes(name)),
          `${name} must still warn`,
        )
      }
      assert.equal(flat(frame()).opacity, undefined)
    } finally {
      warn.mock.restore()
    }
  } finally {
    view.unmount()
  }
})
